class MyCmp {
  someSvc = injectAsync(() => import('..'));
  // with prefetching when the browser is idle:
  // other = injectAsync(() => import('..'), {prefetch: onIdle});

  async onClick() {
    (await this.someSvc()).handleClick();
  }
